		t.Fatalf("%s is not a single JSON object: %v\n%s", what, err, data)
	}
	if err := dec.Decode(&struct{}{}); err != io.EOF {
		t.Fatalf("%s contains more than one JSON value: %v\n%s", what, err, data)
	}
}

